import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;

/**
 * Unit tests for JsonGenerator.writeEmbeddedObject.
 * The current implementation of writeEmbeddedObject is hardcoded to throw a JsonGenerationException.
 */
public class JsonGenerator_writeEmbeddedObject_TriageGen1Test {

    private JsonGenerator jsonGenerator;

    @Before
    public void setUp() {
        // Since JsonGenerator is abstract and has a protected constructor, 
        // we use Mockito to create a mock instance for testing the concrete implementation logic.
        // However, the method provided in the prompt is a concrete method in an abstract class.
        // In a real scenario, this method is part of the Jackson library.
        // To test the specific logic provided:
        jsonGenerator = mock(JsonGenerator.class, Mockito.withSettings().useConstructor().defaultAnswer(Mockito.CALLS_REAL_METHODS));
    }

    /**
     * Tests that calling writeEmbeddedObject throws a JsonGenerationException.
     * This covers the line and branch coverage for the provided implementation.
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_ThrowsException() throws IOException {
        Object testObject = new Object();
        jsonGenerator.writeEmbeddedObject(testObject);
    }

    /**
     * Tests that the exception message is correct as per the implementation.
     */
    @Test
    public void testWriteEmbeddedObject_ExceptionMessage() {
        try {
            jsonGenerator.writeEmbeddedObject(new Object());
            Assert.fail("Expected JsonGenerationException to be thrown");
        } catch (JsonGenerationException e) {
            Assert.assertEquals("No native support for writing embedded objects", e.getOriginalMessage());
        } catch (IOException e) {
            Assert.fail("Expected JsonGenerationException, but caught IOException");
        }
    }

    /**
     * Tests that passing a null object still results in the same exception,
     * as the exception is thrown before any null checks on the parameter.
     */
    @Test(expected = JsonGenerationException.class)
    public void testWriteEmbeddedObject_WithNull_ThrowsException() throws IOException {
        jsonGenerator.writeEmbeddedObject(null);
    }
}
